<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();$rows=$p->query("SELECT o.*,c.name customer FROM orders o LEFT JOIN customers c ON c.id=o.customer_id WHERE o.status NOT IN('Entregue','Cancelado') ORDER BY delivery_date,id")->fetchAll();$stages=['Novo','Arte pendente','Aguardando cliente','Separação','Montagem','Personalização','Conferência','Pronto'];page_head('Produção / Kanban');?>
<div class="kanban"><?php foreach($stages as $stage):?><div class="column"><h3><?=e($stage)?></h3><?php foreach(array_filter($rows,fn($x)=>$x['production_stage']===$stage) as $o):?><div class="ticket"><b><?=e($o['number'])?></b><small><?=e($o['customer']?:'Consumidor')?></small><small>Entrega: <?=e($o['delivery_date'])?> <?=e($o['delivery_time'])?></small><a class="btn" href="order.php?id=<?=$o['id']?>">Abrir</a></div><?php endforeach;?></div><?php endforeach;?></div><?php page_foot();?>